  "about.founderHeading": "📖 關於創始人",
  "about.founder.p1": "大家好，我是康塞普西翁，Luminous StockHaven 的創始人。",
  "about.founder.p2": "我不是來自大型科技公司，也不在企業辦公室裡辦公。我是一名小零售商，和你們一樣。我經營著五家電子商務商店，專營圖書和為愛書之人手工製作的配飾。\n和許多獨立零售商一樣，當我試圖管理多個地點的庫存、將出版商的 ISBN 與我自己的手工 SKU 一併追蹤，並用笨拙的電子表格處理供應商訂單時，我達到了崩潰的邊緣。當我尋找一款能幫助我的應用程式時，我試用了六種不同的選擇。每一種要麼完全不完整，要麼令人難以置信地混亂，要麼就是掠奪性的——為基本工具每月收取數百美元。",
  "about.founder.p3": "對這個盤剝獨立創作者的行業感到沮喪後，我決定構建自己的解決方案。我出於必要性構建了 Luminous StockHaven，為了乾淨、高效、心安地經營我自己的生意。",
  "about.founder.p4": "我決定以誠實、實惠的價格向公眾開放這個平台，因為每一位小商家都值得擁有真正好用、又不危及生計的工具。我們是獨立擁有的，我們堅決守護我們的社區，我們由一位零售商為零售商們而建。",
