  "settings.security.changeEmailTitle": "變更您的帳號電子郵件",
  "settings.security.changeEmailDesc": "將您的帳號移至新電子郵件。您的商店、庫存、團隊和歷史都會跟著移動 — 並且不會開始新的免費試用。所有其他已登入的裝置都會被登出。",
