  "plansLib.includes.support": "應用程式內問題回報",
  "support.category.broken": "有東西壞了",
  "support.category.idea": "想法或建議",
  "support.category.looksWrong": "有東西看起來不對",
  "support.category.other": "其他",
  "support.categoryLabel": "這是關於什麼的？",
  "support.contextNote": "為了讓我們找到問題，您的備註會自動包含您所在的頁面、您的商家和角色（如已選擇）、您的方案、您的應用程式語言，以及您使用的手機或瀏覽器類型。它絕不會包含您的商品、庫存或銷售。",
  "support.description": "有東西壞了、有東西看起來不對，或有想法要分享嗎？請在這裡告訴我們 — 您的備註會直接送交應用程式背後的團隊。",
  "support.errorGeneric": "操作未成功。請再試一次。",
  "support.errorRateLimit": "您今天已傳送了幾份報告 — 謝謝您。請等到明天再傳送更多，讓每份報告都能被妥善閱讀。",
  "support.errorTooLong": "內容比報告可容納的長度還長 — 請稍微刪減後再傳送一次。",
  "support.errorTooShort": "請多告訴我們一點 — 一兩句話有助於我們找到問題。",
  "support.messageLabel": "發生了什麼事？",
  "support.messagePlaceholder": "用您自己的話告訴我們您當時在做什麼，以及哪裡出錯了…",
  "support.sendAnother": "傳送另一份報告",
  "support.sending": "傳送中…",
  "support.sentBody": "我們會閱讀每份報告。如果我們需要更多詳細資料，我們會寫信到您的帳號電子郵件。",
  "support.sentTitle": "謝謝您 — 您的報告已傳送。",
  "support.submit": "傳送報告",
  "support.title": "回報問題",
  "support.urgentNote": "反而是被鎖在帳號外面了嗎？您的備用金鑰可以讓您回來 — 請參閱上方的「安全性與備用金鑰」，或使用登入頁面上的復原入口。",
  "training.lessons.mgr-report-problem.step1": "您的團隊在收銀台工作，那裡最先出現問題。如果應用程式為您團隊中的任何人故障或行為異常，可以在當下從「設定」的「回報問題」回報 — 由他們或由您回報皆可。",
  "training.lessons.mgr-report-problem.step2": "請要求淺白的故事：他們當時在做什麼、他們預期什麼、實際發生了什麼。這樣的一兩句話，勝過事後寫出的完美描述。",
  "training.lessons.mgr-report-problem.step3": "報告會自行附上頁面、商店、傳送者的角色、方案、應用程式語言和裝置類型；商品、庫存和銷售絕不會附上。商店的數字不會隨報告一起離開。",
  "training.lessons.mgr-report-problem.step4": "報告會送交應用程式背後的團隊，每一份都會被閱讀。如果問題將某人鎖在帳號外面，不要等報告：備用金鑰和登入頁面的復原入口可以讓他們回來。",
  "training.lessons.mgr-report-problem.title": "當您的團隊遇到問題時：回報它，不要繞過它",
  "training.lessons.owner-report-problem.step1": "您的訂閱包含一條直達應用程式開發者的專線。開啟「設定」，使用「回報問題」 — 它在每個方案下皆可使用，供您和您團隊的每位成員使用。",
  "training.lessons.owner-report-problem.step2": "用您自己的話說明發生了什麼事：您當時想做什麼，以及應用程式實際做了什麼。表格會自行附上修正所需的詳細資料 — 頁面、商家、角色、方案、語言和裝置；您的商品、庫存和銷售絕不會包含在內。",
  "training.lessons.owner-report-problem.step3": "每份報告都會被儲存並由團隊閱讀。如果更多詳細資料有幫助，他們會回覆傳送者的帳號電子郵件 — 因此答案會送達看到問題的人。",
  "training.lessons.owner-report-problem.step4": "一個例外：如果您或團隊成員完全無法進入帳號，報告不是最快的入口。備用金鑰（設定，安全性與備用金鑰）和登入頁面上的復原入口正是為此而設。",
  "training.lessons.owner-report-problem.title": "回報問題：您直達應用程式團隊的專線",
  "training.lessons.report-problem.step1": "如果應用程式中有東西壞了、看起來不對，或感覺不對勁，您不必忍受它。開啟「設定」，找到「回報問題」 — 它供每個人在每個方案下使用。",
  "training.lessons.report-problem.step2": "選擇您的備註是關於什麼的 — 有東西壞了、有東西看起來不對、一個想法，或其他 — 然後用您自己的話寫下發生了什麼事。您當時在做什麼最有幫助。",
  "training.lessons.report-problem.step3": "您的備註會自動附帶您所在的頁面、您的商店和角色、您的方案、您的應用程式語言，以及您使用的手機或瀏覽器類型 — 這些詳細資料有助於找到問題。它絕不會附帶您的商品、庫存或銷售。",
  "training.lessons.report-problem.step4": "傳送它，它會直接送交應用程式背後的團隊，他們會閱讀每份報告。如果他們需要更多詳細資料，他們會寫信到您的帳號電子郵件。反而是被鎖在帳號外面了嗎？請使用您的備用金鑰或登入頁面上的復原入口 — 那些比報告更快。",
  "training.lessons.report-problem.title": "回報問題：當有東西壞掉時告訴我們",
  "crossStore.transferButton": "移動庫存",
  "crossStore.transferChooseProduct": "選擇一個產品…",
