  "crossStore.transferIntro": "兩家店都是您的，所以您可以直接移動庫存，無需申請。選擇一個產品，說明數量和出發位置，再選擇它到達的商店。兩家店都會立即更新，並且都會保留這次移動的記錄。",
  "crossStore.transferNoTargets": "您還沒有另一家屬於您的商店——庫存只能在屬於您的商店之間移動。",
