  "crossStore.transferTarget": "移至",
  "crossStore.transferTitle": "將庫存移到另一家商店",
  "crossStore.transferToFirstLocation": "它的第一個位置",
  "crossStore.transferToLocation": "到位置",
  "training.lessons.owner-move-stock.step1": "申請是用來請求的；移動是店主的事。在跨店收件箱頁面，「移動庫存」面板讓您——店主——把庫存直接從這家店送到您擁有的另一家店，無需申請，也無需等待。",
  "training.lessons.owner-move-stock.step2": "選擇產品、它出發的位置和數量。應用程式會顯示該位置現有多少庫存，一次移動絕不能超過這個數量。",
  "training.lessons.owner-move-stock.step3": "選擇目標商店，如果願意，還可以選擇那裡的確切位置。如果那家店已經有相同的 SKU，庫存會併入該產品；如果沒有，產品會連同庫存一起複製過去。",
  "training.lessons.owner-move-stock.step4": "兩家店都會保留記錄：這家店顯示轉出，另一家顯示接收。如果移動無法進行——庫存不足，或者另一家店不是您的——任何東西都不會移動，應用程式會說明原因。",
  "training.lessons.owner-move-stock.title": "在您自己的商店之間移動庫存（Business 計劃）",
  "plansLib.feature.pricing": "清倉與限時特價定價",
  "plansLib.includes.pricing": "清倉和限時特價銷售定價",
  "pricing.businessOnly": "清倉和限時特價定價屬於 Business 計劃。",
  "pricing.clearanceBadge": "清倉",
  "pricing.clearanceHint": "永久降價。它會一直保持，直到您改回常規價格。",
  "pricing.clearancePriceLabel": "清倉價",
  "pricing.endLabel": "結束",
  "pricing.modeClearance": "清倉",
  "pricing.modeLabel": "定價",
  "pricing.modeRegular": "常規價格",
  "pricing.modeRollback": "限時特價（臨時促銷）",
  "pricing.rollbackBadge": "限時特價",
  "pricing.rollbackHint": "在促銷期間，常規價格會被保留，並顯示在特價旁邊。結束日期過後，價格會自動恢復為常規價格。",
  "pricing.rollbackStarts": "限時特價將於 {date} 開始",
  "pricing.salePriceLabel": "特價",
  "pricing.sectionTitle": "銷售定價",
  "pricing.startLabel": "開始",
  "training.lessons.mgr-pricing.step1": "在 Business 上，產品表單有一個「銷售定價」部分。清倉是永久降價——設定後就保持不變。限時特價是帶日期的促銷：設定特價、開始日期和結束日期。",
  "training.lessons.mgr-pricing.step2": "您永遠不必重新輸入常規價格：它保留在產品上，並顯示在產品列表和掃描器中的特價旁邊，這樣任何人都能看到該商品通常的價格。",
  "training.lessons.mgr-pricing.step3": "限時特價開始時打印新的價格標籤——標籤打印的是客戶當天支付的價格。結束日期過後，價格會自動恢復為常規價格；在您刷新貨架時重新打印常規標籤。",
  "training.lessons.mgr-pricing.step4": "如果「銷售定價」部分顯示為鎖定，說明該企業不在 Business 計劃上——銷售定價屬於該計劃，只有店主才能更改計劃。",
  "training.lessons.mgr-pricing.title": "做促銷：清倉與限時特價",
  "training.lessons.owner-pricing.step1": "產品表單中的「銷售定價」下有兩種降價。清倉是永久的：設定清倉價後，它會一直保持低價，直到您改回來。限時特價是臨時促銷——一個更低的價格，帶有開始日期和結束日期，就像您在大商店裡已經熟悉的促銷一樣。",
  "training.lessons.owner-pricing.step2": "常規價格永遠不會被抹掉。限時特價運行期間，應用程式會顯示特價，並在旁邊顯示常規價格；打印的標籤使用特價，這樣貨架與收銀台一致。",
  "training.lessons.owner-pricing.step3": "結束日期過後，價格會自動回到常規價格——無需記住任何事情，也無需撤銷。尚未開始的限時特價會在產品列表上直接說明它的開始日期。",
  "training.lessons.owner-pricing.step4": "銷售定價是 Business 計劃的功能。在 Essentials 上，這些欄位保持鎖定；如果一家企業降到 Essentials 後再回來，它的清倉和限時特價設定仍然原封不動，正如當初離開時一樣。",
  "training.lessons.owner-pricing.title": "清倉與限時特價定價（Business 計劃）",
