  "training.lessons.owner-shipping-labels.step1": "列印中心在兩種方案中都有「郵寄標籤」樣式：選擇一個客戶訂單，即可列印一張 4×6 標籤，上面有買家姓名和地址，以及作為寄件人的您的店鋪。",
  "training.lessons.owner-shipping-labels.step2": "這張標籤和所有客戶單據一樣是白標的：上面只有您的店鋪名稱——絕不會出現本應用程式的名稱——所以從您店裡寄出的包裹看起來就是來自您的店。",
  "training.lessons.owner-shipping-labels.step3": "客戶的地址會隨其訂單保留到最後一次訂單後 90 天；如果訂單存有地址，標籤會從該地址開始；列印時為一次性標籤輸入的地址不會被儲存回去。姓名仍會從訂單填入，這樣標籤與單據一致。",
  "training.lessons.owner-shipping-labels.step4": "這張標籤透過與所有標籤相同的四種連接列印——藍牙、Wi-Fi、乙太網路和 USB——4×6 熱感印表機是它的標準尺寸。",
  "training.lessons.owner-shipping-labels.step5": "改為向承運商購買了郵資？在同一區域，您可以上傳承運商的標籤檔案 — PDF、PNG 或 JPG — 它會永久保存在訂單上：您的記錄，以防萬一，隨時都在手邊。它以真實的 4×6 尺寸列印。本應用從不出售郵資，所以承運商的價格是唯一的價格 — 並且永遠是正確的價格。",
  "training.lessons.owner-shipping-labels.title": "客戶訂單郵寄標籤",
  "training.lessons.print-shipping-label.step1": "訂單準備好寄出時，打開列印中心，選擇「郵寄標籤」樣式，再選擇客戶訂單。買家姓名會從訂單自動填入。",
  "training.lessons.print-shipping-label.step2": "檢查包裹要寄往的地址。當訂單帶有客戶地址時 — 會保留到最後一次訂單後 90 天 — 它會自動填入；您在列印時輸入的地址不會被儲存回去，所以列印前請仔細核對郵遞區號和最後一行。",
  "training.lessons.print-shipping-label.step3": "您的店鋪名稱會作為寄件人列印在頂部。如果還想把您的地址也印在標籤上，把它輸入寄件人地址欄；不想出現就留空。",
  "training.lessons.print-shipping-label.step4": "用 4×6 標籤列印——熱感標籤印表機是常見選擇——或透過瀏覽器列印按鈕用任何印表機列印。把標籤平貼在包裹上，不要折到邊緣。",
  "training.lessons.print-shipping-label.step5": "如果郵資是向承運商購買的，請改為把他們的標籤檔案保存在訂單上：在「您的承運商標籤」區域上傳承運商給您的 PDF、PNG 或 JPG。它會作為您的記錄留在訂單上，並以真實的 4×6 尺寸列印 — 而當您更願意使用時，應用自己的地址標籤也隨時都在。",
  "training.lessons.print-shipping-label.title": "列印郵寄標籤",
  "pos.provider.clover": "Clover",
