  "settings.install.iosSteps": "在 Safari 中，點按共享按鈕，然後點按「加入主畫面」，然後點按「加入」。應用程式會像任何其他應用程式一樣位於您的主畫面上。",
  "settings.install.androidSteps": "在瀏覽器中，點按選單（三個點），然後點按「安裝應用程式」或「加入主畫面」，並確認。應用程式會像任何其他應用程式一樣位於您的主畫面上。",
  "settings.install.desktopSteps": "在瀏覽器的網址列中，如果顯示安裝圖示，請按一下它。如果沒有圖示，請開啟瀏覽器選單並選擇「安裝 Luminous StockHaven」或「加入桌面」。",
  "staffWelcome.title": "歡迎來到 Luminous StockHaven",
  "staffWelcome.defaultGreeting": "您好，{name}",
  "staffWelcome.defaultStoreLine": "您現在是 {store} 的一員 — 這家店也是您的店。",
  "staffWelcome.defaultTrainingLine": "您的培訓已準備好 — 它會一步步帶您了解一切。",
  "staffWelcome.defaultGladLine": "我們很高興您來到這裡。",
  "staffWelcome.start": "開始我的培訓",
  "staffWelcome.skip": "暫時跳過",
  "staffWelcome.editor.title": "給新員工的歡迎訊息",
  "staffWelcome.editor.description": "新員工在首次登入時、在一切之前只讀一次的話。用您自己的話來寫，讓它感覺像您的店。",
  "staffWelcome.editor.permanentNote": "第一行是應用程式本身 — 它始終顯示，無法更改或刪除。",
  "staffWelcome.editor.tokens": "在應該出現此人名字的地方寫 {name}，在應該出現您的店名的地方寫 {store} — 應用程式會為每個人填好。",
  "staffWelcome.editor.emptyNote": "將框留空即可使用應用程式的標準歡迎語（在框中淡淡地顯示）。新員工永遠不會看到空白頁面。",
  "staffWelcome.editor.save": "儲存歡迎訊息",
  "staffWelcome.editor.saved": "歡迎訊息已儲存。",
  "training.lessons.staff-shift-windows.title": "您的登入跟隨您的班次",
  "training.lessons.staff-shift-windows.step1": "您可以從預定班次開始前約 10 分鐘起登入。在此之前，應用程式保持關閉 — 登入頁面會告訴您下一個班次何時開始。",
  "training.lessons.staff-shift-windows.step2": "一旦您打卡下班，您有 10 分鐘查看您的頁面，因為您將被登出，直到您的下一個預定日期。",
  "training.lessons.staff-shift-windows.step3": "如果您在這 10 分鐘內重新打卡上班，登出將被取消，您將保持登入狀態。",
  "training.lessons.staff-shift-windows.step4": "排班表上沒有班次意味著那天無法登入。如果您認為自己應該在排班表上，請詢問您的經理或所有者 — 發布打開您大門的排班表的是他們。",
  "training.lessons.manager-shift-windows.title": "發布排班表會開啟和關閉存取權限",
  "training.lessons.manager-shift-windows.step1": "您為團隊發布的排班表不僅僅是班次列表：它開啟和關閉每個人的應用程式存取權限。團隊成員可以從您為他發布的班次前約 10 分鐘起登入 — 不能更早。",
  "training.lessons.manager-shift-windows.step2": "當他打卡下班時，他有大約 10 分鐘查看他的時間，然後應用程式會將他登出，直到他的下一個預定班次。那天沒有發布班次意味著他那天無法登入。",
  "training.lessons.manager-shift-windows.step3": "請謹慎發布班次：缺失或錯誤的班次會把一個人鎖在應用程式之外，而不僅僅是排班表之外。如果有人說他進不來，請先檢查他的排班表。",
  "training.lessons.manager-shift-windows.step4": "您自己的存取權限也以同樣的方式運作，只是高一個級別：所有者為您發布的排班表會在您的班次前約 10 分鐘開啟您的視窗，並在您打卡下班後約 10 分鐘關閉您的會話。",
  "training.lessons.owner-shift-windows.title": "班次視窗：排班表開啟和關閉存取權限",
  "training.lessons.owner-shift-windows.step1": "存取權限跟隨您發布的排班表。員工或經理可以從其預定班次前約 10 分鐘起登入 — 不能更早。在班次之外，應用程式對他們保持關閉，這樣店的資訊就留在值班人員手中。",
  "training.lessons.owner-shift-windows.step2": "當他們打卡下班時，他們有大約 10 分鐘查看他們的時間，然後應用程式會自行將他們登出，直到他們的下一個預定班次。在這 10 分鐘內重新打卡上班會取消登出。",
  "training.lessons.owner-shift-windows.step3": "那天沒有發布班次意味著那天沒有視窗：如果某人不在排班表上，他就無法登入。在勞動力中發布排班表，他的大門就會隨之開啟。",
  "training.lessons.owner-shift-windows.step4": "您是唯一的例外：沒有人給所有者排班，所以您的登入永遠沒有視窗。經理受您為他發布的排班表的限制，就像員工受為他們發布的排班表的限制一樣。",
  "settings.install.ownerNote": "如果您的應用商店哪天讓您無法使用該應用，此連結可讓您直接從本網站取得應用 — 無需商店。",
