  "apiErrors.invalidValue.recordingNotPrepared": "該錄音無法準備 — 請重新錄製。",
  "training.lessons.messages-private.step5": "您也可以傳送語音留言：點按訊息框旁邊的麥克風，說話，然後點按停止。先聽一遍 — 然後傳送，或者刪除後重新錄製。當有人傳給您時，點按播放即可聽到對方真實的聲音。",
  "training.lessons.owner-messages-oversight.step5": "已讀標記：當團隊成員閱讀了您傳送的訊息時，您會看到它被標記為已讀。員工和經理以同樣的方式互相看到對方的已讀標記，雙向都是如此。",
  "training.lessons.owner-messages-oversight.step6": "您自己的閱讀是不可見的。當您閱讀員工傳給您的訊息時，對方永遠不會看到已讀標記 — 而且您不需要告訴團隊，他們的對話儲存在應用程式中，而您作為店主可以閱讀它們。這種監督是您照看店鋪的一部分。",
  "training.lessons.owner-messages-oversight.step7": "對於員工之間的負面訊息，您如何處理由您決定。可以置之不理，私下與某人談談，或者採取行動 — 選擇權在您，您永遠不需要說出您是在哪裡看到的。",
