  "settings.policies.title": "您商店的政策與條款",
  "settings.policies.ownerDescription": "您的商店,您的規則。在這裡寫下您商店的政策和條款 — 可以直接輸入,也可以上傳檔案。每位新團隊成員在開始時都會看到一次,您的整個團隊隨時可以在這裡閱讀。只有您可以更改它們。",
