  "training.lessons.owner-store-policies.title": "您商店的政策與條款",
  "training.lessons.owner-store-policies.step1": "開啟設定,找到「商店政策與條款」卡片。它包含兩份文件:您的商店政策 — 您商店的內部規則 — 以及您的條款與條件。",
  "training.lessons.owner-store-policies.step2": "每份文件都可以直接在那裡輸入,或作為檔案上傳(PDF、文字、Word 或 OpenDocument,最大 25 MB)。兩者只能選其一:儲存文字會取代檔案,上傳檔案會取代文字。移除一份文件會將其清空。",
  "training.lessons.owner-store-policies.step3": "您的團隊會在他們第一次開始時的歡迎頁面上看到這兩份文件一次,並且隨時可以在他們的設定中閱讀。對您的團隊來說,它們是唯讀的 — 只有您可以撰寫或更改它們。",
  "training.lessons.owner-store-policies.step4": "每個商家都保存自己的文件:您在這裡寫的內容只屬於這家商店,永遠不會出現在另一家商家中。Luminous StockHaven 自己的條款和政策位於設定中您文件的旁邊,每個人也可以閱讀它們。",
  "training.lessons.welcome-basics.step5": "您商店的政策和條款會在您的歡迎頁面上顯示一次,並保存在設定中,您隨時可以在那裡閱讀。",
