  "settings.policyQuiz.openLabel": "開放題",
  "settings.policyQuiz.passLine": "及格線",
  "settings.policyQuiz.passLineHint": "完成這項培訓所需的分數 — 只計算選擇題的答案。",
  "settings.policyQuiz.question": "問題",
  "settings.policyQuiz.remove": "移除",
  "settings.policyQuiz.save": "儲存問題",
  "settings.policyQuiz.saved": "問題已儲存。",
  "settings.policyQuiz.title": "給您團隊的問題",
  "staff.memberDialog.trainingAccessHint": "閱讀店鋪政策和條款是面向所有人的。這些勾選項分配的是所有者在設定中每份文件旁邊建立的測驗培訓。",
  "staffLib.area.trainingAccess": "政策測驗培訓",
  "staffLib.perm.trainingPoliciesQuiz": "店鋪政策測驗培訓",
  "staffLib.perm.trainingTermsQuiz": "條款與條件測驗培訓",
  "training.comment.placeholder": "關於這節課的任何想法…",
  "training.comment.send": "傳送留言",
  "training.comment.sent": "您的留言已提交給所有者。",
  "training.comment.title": "給所有者留言",
  "training.lessons.download-app.step1": "Luminous StockHaven 可以像真正的應用程式一樣裝在您的手機或電腦上 — 不需要應用程式商店。",
  "training.lessons.download-app.step2": "打開設定，找到下載應用程式卡片。每個角色、兩種方案都有這張卡片。",
  "training.lessons.download-app.step3": "點安裝按鈕，按裝置的提示操作。應用程式會帶著店鋪的名稱和圖示出現在主畫面上。",
  "training.lessons.download-app.step4": "從那以後就從主畫面打開它 — 登入方式相同，顯示的也是同一家店鋪。",
  "training.lessons.download-app.title": "把應用程式下載到您的裝置",
  "training.lessons.mgr-tax-rate.step1": "訂單可以帶一個銷售稅率。稅率本身由所有者在設定中設定；整個店鋪只有一個稅率。",
  "training.lessons.mgr-tax-rate.step2": "當所有者在您的員工記錄中為您勾選稅費部分時，稅率也會出現在您的設定中，您可以在那裡保持它最新。",
  "training.lessons.mgr-tax-rate.step3": "稅率是一個百分比 — 8.25 表示顧客在訂單商品金額之外還要付 8.25% 的稅。",
  "training.lessons.mgr-tax-rate.step4": "稅率變化時，新訂單使用新稅率。已經下的訂單保留下單時的稅率。",
  "training.lessons.mgr-tax-rate.step5": "如果店主將稅額切換為自動，新訂單會在州出現在訂單上的那一刻，用客戶所在州的基本稅率填入稅額，州變更時還會重新填入。這些是各州的基本稅率；地方稅可能還會增加。沒有州、或來自美國境外的訂單，使用商店的固定稅率——而在訂單上輸入的稅額始終優先。",
  "training.lessons.mgr-tax-rate.title": "店鋪的稅率",
  "training.lessons.owner-confidentiality.step5": "這是全貌。您的團隊看到的是他們自己的工作 — 他們的排班、任務、薪資單、訊息，以及他們角色能打開的店鋪頁面。他們永遠看不到您的試用、企業用的是哪個方案、方案多少錢、付款是否成功，或者是否達到了方案上限。涉及錢的頁面 — 帳單、發票、付款方式 — 永遠只有所有者能看。",
  "training.lessons.owner-confidentiality.step6": "如果帳戶被停用，您的團隊看到的正是這條訊息：「更改目前已關閉。目前無法新增或更改任何內容 — 如果您需要什麼，請詢問商家所有者。」 其中沒有提到方案、價格或付款。",
  "training.lessons.owner-confidentiality.step7": "而當方案上限導致某事被攔下時，顯示的正是這條訊息：「現在無法加入這個 — 請向企業所有者詢問。」 它從不說達到了上限 — 那只在您和應用程式之間。",
  "training.lessons.staff-builds.step1": "組合是把產品拼成一個可以出售的東西 — 禮包、套裝、禮品套裝。組合在選單的組合頁面裡。",
  "training.lessons.staff-builds.step2": "打開一個組合，查看它的組成：每個部件產品，以及組合各用多少個。",
  "training.lessons.staff-builds.step3": "組合被製作或售出時，其部件的庫存會隨之變動 — 應用程式會為您保持數量準確。",
  "training.lessons.staff-builds.step4": "如果缺少某個部件或數量看起來不對，請告訴您的經理，不要猜測 — 組合會同時影響許多產品。",
  "training.lessons.staff-builds.title": "組合與禮包",
  "training.lessons.staff-cross-store.step1": "當您的企業有不止一家店鋪或據點時，店鋪之間可以互相請求庫存。這些請求會進入跨店收件匣。",
  "training.lessons.staff-cross-store.step2": "從選單打開收件匣，查看另一家店鋪在請求什麼，以及您的店鋪收到了什麼。",
  "training.lessons.staff-cross-store.step3": "只按經理教您的方式回覆請求 — 發出庫存會改變您自己店鋪的數量。",
  "training.lessons.staff-cross-store.step4": "如果請求看起來不對 — 物品錯了，或者數量超過您有的 — 不要猜。請向經理報告。",
  "training.lessons.staff-cross-store.title": "跨店收件匣",
  "training.lessons.staff-reports.step1": "報表把店鋪的數字 — 銷售、庫存等等 — 彙總到一處。報表在選單裡。",
  "training.lessons.staff-reports.step2": "打開一份報表，查看它所涵蓋日期的數字。日期是報表的一部分：同一份報表換一週，講的就是另一個故事。",
  "training.lessons.staff-reports.step3": "有些報表可以儲存為檔案匯出。只有在經理或所有者要求時，才把報表匯出儲存。",
  "training.lessons.staff-reports.step4": "報表的數字來自店鋪的真實工作 — 訂單、盤點和調動 — 所以其他地方都如實輸入，報表才會真實。",
  "training.lessons.staff-reports.title": "閱讀報表",
  "training.lessons.welcome-basics.step6": "完成後請登出：每個頁面最底部、版權行正上方都有一個登出連結。登出會在所有裝置上都登出 — 這樣就沒人能在共用畫面上進入您的帳戶。",
