  "plansLib.includes.profilePhotos": "為整個團隊提供個人資料照片，由所有者批准",
  "apiErrors.notFound.photoFound": "找不到照片。",
  "apiErrors.profileOwnerNameOnly": "只有企業所有者才能設定所有者名字。",
  "apiErrors.profilePhotosApproveOwnerOnly": "只有企業所有者才能批准團隊照片。",
  "apiErrors.profilePhotosNoneWaiting": "該團隊成員沒有等待批准的照片。",
  "apiErrors.profileOwnerNameTooLong": "請將您的名字控制在 80 個字元以內。",
  "training.lessons.your-profile-photo.title": "您的個人資料照片",
  "training.lessons.your-profile-photo.step1": "所有者批准後，您的照片會出現在應用程式頂部您的名字旁邊、「員工」頁面上，以及您的訊息旁邊。在此之前，只會顯示您的姓名縮寫。",
  "training.lessons.your-profile-photo.step2": "開啟「設定」，找到「您的個人資料照片」。選擇一張您自己的照片並傳送。它會傳送給所有者批准——在等待期間不會出現在任何地方。",
  "training.lessons.your-profile-photo.step3": "所有者批准後，您的鈴鐺會響起，您的照片開始顯示。如果未獲批准，請選擇一張不同的照片並重新傳送。",
  "training.lessons.your-profile-photo.step4": "更換照片的方式相同：新照片等待批准，在新照片獲批之前，您的目前照片保持不變。如果更換未獲批准，您保留原來的照片。",
  "training.lessons.owner-profile-photos.title": "個人資料照片與您的名字",
  "training.lessons.owner-profile-photos.step1": "每個人的照片都會顯示在其名字旁邊——在應用程式頂部、您的「員工」頁面上，以及他們的訊息旁邊。團隊成員的照片在您批准之前不會出現在任何地方——批准權只屬於您，任何人都不能批准自己的照片。",
  "training.lessons.owner-profile-photos.step2": "當有人傳送照片時，您的鈴鐺會響起。開啟「員工」頁面查看，然後選擇「批准」或「不批准」。如果您不批准，系統會通知對方選擇另一張照片。",
  "training.lessons.owner-profile-photos.step3": "如果有人更換照片，新照片同樣等待您的批准。在等待期間，他們的目前照片保持不變——如果您不批准更換，它也會繼續保留。",
  "training.lessons.owner-profile-photos.step4": "您自己的照片無需批准：在「設定」的「您的個人資料照片」下設定。同一張卡片還包含您的名字——您在那裡設定的名字會在團隊看到的所有地方取代「所有者」這個詞，包括應用程式內和「訊息」中。",
