  "training.lessons.mgr-clock-callin.title": "臨時叫班與考勤修正",
  "training.lessons.mgr-clock-callin.step1": "店主可以給經理兩個分開的勾。臨時叫班讓您可以為一名員工打開叫班窗口，考勤牌與漏打的下班卡讓您可以查看團隊的考勤牌，並在員工頁面修正考勤記錄。每個勾都獨立起作用 — 經理可以只有其中一個。",
  "training.lessons.mgr-clock-callin.step2": "叫班窗口讓一個人在沒有班次覆蓋時也能登入並打卡。在員工頁面，從「叫班與漏打下班卡」卡片打開它。",
  "training.lessons.mgr-clock-callin.step3": "窗口會一直開著，直到那個人打了下班卡 — 之後是通常的10分鐘登出寬限 — 或者直到您或店主提前關閉它。沒有任何東西會自動關閉它。",
  "training.lessons.mgr-clock-callin.step4": "當有人忘記打下班卡時，排班一結束，他的記錄就會在員工頁面和工資單中被標記，您和店主都會收到通知。記錄會一直計時，直到被修正。",
  "training.lessons.mgr-clock-callin.step5": "在員工頁面修正記錄：設定上班、下班和休息時間。經理只能修正員工的記錄 — 經理自己的記錄由店主修正。",
  "staffLib.perm.staffDocuments": "員工文件",
  "staffLib.area.documentsAccess": "員工文件",
  "staff.memberDialog.documentsAccessHint": "僅限經理 — 勾選此項後，這位經理可以開啟員工成員的文件檔案：為每個人保存的文書，如 W-4 表格、求職申請和身分證件副本。系統會先請您確認 — 這些檔案含有社會安全號碼和出生日期。此勾選對普通員工不起任何作用。",
  "staff.documentsWarning.body": "此人將能夠查看有關您員工成員的機密資訊，包括社會安全號碼和出生日期。",
