  "staff.documents.mineTitle": "我的文件",
  "staff.documents.mineDesc": "您的店主為您保存在檔案中的文書 — W-4 表格、您的求職申請、稅務表格、身分證件副本。這是您自己的檔案：其中任何內容您都可以開啟、下載和列印，但這裡的任何內容都不能更改。",
