  "apiErrors.documents.notFound": "該文件不在檔案中。",
  "training.lessons.owner-staff-documents.title": "員工文件",
  "training.lessons.owner-staff-documents.step1": "您團隊中的每個人在「員工」頁面都有一個文件檔案。上傳您為他們保存的文書 — W-4 表格、他們的求職申請、稅務表格、他們的身分證件副本 — 並為它們起個標題，或保留檔案名稱。",
  "training.lessons.owner-staff-documents.step2": "每次上傳都會保留。新增較新的版本永遠不會刪除舊版本 — 所有版本都會留在清單中，最新在前，每個版本都有自己的日期和上傳者姓名。",
  "training.lessons.owner-staff-documents.step3": "只有您能查看員工文件，除非您在某位經理的成員記錄中授予其「員工文件」勾選。此勾選預設關閉，任何角色都不自帶。",
  "training.lessons.owner-staff-documents.step4": "在勾選開啟之前，會有一條警告說明其含義：此人將能夠查看有關您員工成員的機密資訊，包括社會安全號碼和出生日期。文件所屬之人可以開啟自己的檔案來查看、下載和列印 — 但永遠不能更改其中的任何內容。",
  "training.lessons.mgr-staff-documents.title": "員工文件",
  "training.lessons.mgr-staff-documents.step1": "店主已將「員工文件」勾選託付給您。在「員工」頁面，您可以開啟團隊中員工成員的文件檔案。",
  "training.lessons.mgr-staff-documents.step2": "每個檔案都保留每個版本：當您新增較新的副本時，舊副本仍列在其下方，最新在前，每個版本都有自己的日期和上傳者姓名。",
  "training.lessons.mgr-staff-documents.step3": "這些檔案可能含有社會安全號碼、出生日期和其他私人資訊。只開啟您需要的內容，永遠不要將文件分享到企業之外。",
  "training.lessons.mgr-staff-documents.step4": "店主可以隨時收回勾選，門會立即關閉。經理自己的文件只留在店主處 — 其他任何經理都無法開啟，不過和所有人一樣，您也可以開啟自己的檔案來查看。",
  "nav.group.restaurant": "餐廳",
  "nav.recipes": "配方與菜餚",
  "nav.restaurant": "餐廳",
  "nav.orderGuide": "訂購指南",
  "plansLib.businessIncludes.restaurant": "餐廳專區——可自動扣減配料的配方和真實菜餚成本",
  "plansLib.businessIncludes.orderGuide": "標準庫存量和供應商訂購指南",
  "staffLib.perm.restaurantBuild": "製作和編輯配方",
  "staffLib.perm.restaurantPars": "設定標準庫存量",
  "staffLib.perm.restaurantMoney": "查看菜餚成本和利潤率",
  "staffLib.area.restaurantAccess": "餐廳存取權限",
  "staff.memberDialog.restaurantAccessHint": "查看餐廳專區對團隊所有人開放。這些勾選可將製作配方、設定標準量和查看菜餚真實成本的權限交給他人。它們僅在 Business 方案下有效。",
  "training.module.restaurant": "餐廳",
  "training.lessons.owner-restaurant.title": "餐廳專區，老闆版",
  "training.lessons.owner-restaurant.step1": "餐廳專區存放著您的配方和菜餚。將配方連結到您出售的產品並設為啟用，該產品每售出一份，其配料就會自動從貨架上扣減——無論是透過訂單、收銀台還是掃描都一樣。",
  "training.lessons.owner-restaurant.step2": "配方可以將另一份配方用作配料——如義大利麵菜餚中的醬汁——成本和貨架數量會透過兩者逐層匯總。",
  "training.lessons.owner-restaurant.step3": "設定做一份配方可產出多少，以及每種配料的產出率——修整和烹飪後實際可供食用的部分。真實成本是按可食用的部分計算的；貨架上仍會扣減您購買的全部數量。",
  "training.lessons.owner-restaurant.step4": "Q 係數涵蓋了配方從不會列出的小東西——鹽、油、擠一點檸檬汁。它只將該百分比加到菜餚成本中；它絕不會從貨架上扣減任何東西。",
  "training.lessons.owner-restaurant.step5": "菜餚金額——真實成本和食材成本率——屬於您，以及您授予「查看菜餚成本」勾選的任何團隊成員。其他人只能看到菜餚、它的價格和配料，任何地方都沒有成本數字。",
  "training.lessons.staff-restaurant-view.title": "查看菜餚和配方",
  "training.lessons.staff-restaurant-view.step1": "在 Business 方案下，餐廳專區列出菜餚和配方。開啟一個即可查看它的照片、所含配料，以及做一份可產出多少。",
  "training.lessons.staff-restaurant-view.step2": "當帶有啟用配方的菜餚售出時，其配料會自動從貨架上扣減。仍為草稿的配方不會扣減任何東西。",
  "training.lessons.staff-restaurant-view.step3": "訂購指南顯示要購買什麼：對於每種設有標準量的配料，它計算標準量減去現有庫存和已訂購量，並向上取整到供應商的包裝規格。",
  "training.lessons.staff-restaurant-view.step4": "菜餚成本由老闆決定是否分享。如果一道菜不顯示成本，那是有意為之——如需了解，請詢問老闆。",
  "training.lessons.mgr-restaurant-build.title": "製作配方",
  "training.lessons.mgr-restaurant-build.step1": "老闆已將「製作配方」勾選託付給您。在餐廳專區，您可以逐行新增配料來編寫配方——每一行都是已在庫存中的產品，以及做一份所需的數量。",
  "training.lessons.mgr-restaurant-build.step2": "配方也可以從檔案匯入：每行一種配料，其名稱或 SKU 以及數量。應用程式無法配對的行會明確告知您，絕不會悄悄丟棄。",
  "training.lessons.mgr-restaurant-build.step3": "配方也可以將另一份配方用作配料，並且配方在設為啟用並連結到您出售的產品之前，一直是草稿——不會從任何貨架上扣減任何東西。",
  "training.lessons.mgr-restaurant-build.step4": "請如實設定每種配料的產出率：它是修整和烹飪後剩下的比例，菜餚的真實成本就是據此計算的。",
  "training.lessons.mgr-restaurant-pars.title": "設定標準量和訂購指南",
  "training.lessons.mgr-restaurant-pars.step1": "老闆已將「標準量」勾選託付給您。標準量是指一種配料應該備有多少——可針對整個企業，或其某個地點。",
  "training.lessons.mgr-restaurant-pars.step2": "將包裝規格設定為供應商銷售該配料的方式——一箱十二個、一袋五十個。訂購指南會將每一處缺口向上取整為整包。",
  "training.lessons.mgr-restaurant-pars.step3": "指南計算標準量減去現有庫存，再減去已訂購量，並按供應商分組，因此一週的採購讀起來就是每個供應商一份簡短清單。",
  "training.lessons.mgr-restaurant-pars.step4": "傳送指南會在採購中為該供應商寫下一份採購單草稿——與各處相同的採購單，隨時可供檢查和傳送。",
  "training.lessons.mgr-restaurant-money.title": "查看菜餚金額",
  "training.lessons.mgr-restaurant-money.step1": "老闆已將「菜餚金額」勾選託付給您。現在菜餚會顯示其真實成本——配料的成本，並透過其中包含的任何配方逐層匯總——就在售價旁邊。",
  "training.lessons.mgr-restaurant-money.step2": "食材成本率是真實成本除以售價。它是按每種配料在產出率之後可供食用的部分計算的。",
  "training.lessons.mgr-restaurant-money.step3": "Q 係數如果配方帶有它，已經包含在真實成本中——它涵蓋了任何配方都不會列出的小東西，如鹽和油。",
  "training.lessons.mgr-restaurant-money.step4": "菜餚金額只保留在企業內部。老闆可隨時收回此勾選，這些數字會立即從您的畫面上消失。",
  "restaurant.eyebrow": "餐廳",
  "restaurant.title": "配方與菜餚",
  "restaurant.subtitle": "將菜餚連結到您出售的產品，它的配料就會自行處理——每次銷售都會從貨架上扣減它們，菜餚頁面會顯示它的真實成本。",
