  "nav.xstoreMessages": "跨店訊息",
  "plansLib.businessIncludes.xstoreMessages": "跨店訊息——您的整個團隊，遍及每一家企業",
  "xstore.title": "跨店訊息",
  "xstore.help": "此帳戶的每一個人，遍及您的所有企業，都匯集在同一個收件匣中。您可以在這裡傳訊息給他們任何人——文字或語音，並帶有已送達和已讀標記。您的店內訊息維持原樣。",
  "xstore.empty": "尚無任何對話。用「新訊息」開始一段對話吧。",
  "xstore.noPeople": "目前還沒有其他人可以傳訊息。成員加入您的某一家企業並登入後，就會顯示在這裡。",
  "xstore.deliveredLabel": "已送達",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "跨店訊息是商業版方案的一部分。",
  "apiErrors.invalidValue.personNotPartAccount": "那個人不屬於此帳戶。",
  "training.lessons.owner-xstore-messages.title": "跨店訊息，店主篇",
  "training.lessons.owner-xstore-messages.step1": "跨店訊息是第二個收件匣，與店內訊息分開。店內訊息用於您目前所在的商店；而這個入口可以聯絡到您帳戶上的每一個人，遍及您擁有的每一家企業——最多五家。",
  "training.lessons.owner-xstore-messages.step2": "從選單開啟跨店訊息，即可與清單上的任何人開始對話。清單會顯示您所有企業中已登入的每一位團隊成員，以及他們工作的商店。",
  "training.lessons.owner-xstore-messages.step3": "照片也會一併顯示：每個人都會顯示其已核准的大頭貼照片，沒有照片時則顯示姓名縮寫。每則訊息都帶有傳送的日期和時間。",
  "training.lessons.owner-xstore-messages.step4": "在您自己傳送的訊息下方，訊息送達後您會看到「已送達」，對方開啟對話後會看到「已讀」。語音訊息在這裡也能使用，與店內訊息完全一樣。",
  "training.lessons.owner-xstore-messages.step5": "這裡的對話僅對對話中的兩個人私密。您對店內訊息的查看權限不會延伸到其他商店。",
  "training.lessons.mgr-xstore-messages.title": "跨店訊息，經理篇",
  "training.lessons.mgr-xstore-messages.step1": "跨店訊息可以聯絡到此帳戶上的每一個人，遍及每一家企業——而不只是您目前所在的商店。它位於選單中，與店內訊息分開。",
  "training.lessons.mgr-xstore-messages.step2": "從清單開始一段對話：每一位已登入的團隊成員都在那裡，姓名旁標示著他們工作的商店。",
  "training.lessons.mgr-xstore-messages.step3": "傳送文字，或者錄製語音訊息。語音訊息傳送前，您可以回聽、捨棄或傳送——與店內訊息一樣。",
  "training.lessons.mgr-xstore-messages.step4": "您的訊息送達時會顯示「已送達」，對方開啟對話時會顯示「已讀」。每個姓名旁的照片是該人已核准的大頭貼照片。",
  "training.lessons.staff-xstore-messages.title": "跨店訊息",
  "training.lessons.staff-xstore-messages.step1": "跨店訊息讓您可以聯絡到此帳戶上的任何人，無論他們在店主的哪一家企業——向另一家商店提問，再也不必等待。",
  "training.lessons.staff-xstore-messages.step2": "從選單開啟它，選擇對方，然後寫訊息。如果您需要的人不在清單中，表示他們還沒有登入——他們一登入就會顯示出來。",
  "training.lessons.staff-xstore-messages.step3": "您也可以在這裡傳送語音訊息：錄製、回聽，然後傳送或捨棄。每則訊息都會顯示傳送的日期和時間。",
  "training.lessons.staff-xstore-messages.step4": "當您傳送訊息時，送達後會顯示「已送達」，對方開啟對話後會顯示「已讀」。對話僅對您和對方私密。",
