  "training.lessons.owner-restaurant-ops.title": "餐廳營運，老闆版",
  "training.lessons.owner-restaurant-ops.step1": "供應商發票位於餐廳專區。輸入供應商開出的帳單，連結到其採購單，應用程式會三方核對——已訂購、已收貨和已開票，並列顯示——並標記任何短缺、超量或以不同價格開票的品項。",
  "training.lessons.owner-restaurant-ops.step2": "當發票品項以與記錄成本不同的價格為產品開票時，發票頁面會開啟價格提醒。接受提醒會將產品成本更新為開票價格；忽略它則保持成本不變。",
  "training.lessons.owner-restaurant-ops.step3": "損耗記錄會記錄廚房扔掉的一切，附原因——變質、生產過剩、備餐失誤、退回、灑漏或其他——記錄它會自動將庫存從貨架扣除。保存期限批次按先到期先出列出，因此最早的保存期限先被使用，您可以為您勾選的批次列印日期標籤。",
  "training.lessons.owner-restaurant-ops.step4": "過敏原矩陣根據每道菜配方的配料，對照九大主要過敏原計算其過敏原，讓客人的問題從記錄中得到回答，而不是憑記憶。溫度記錄、沽清看板和員工餐對整個團隊開放——無需勾選——因為日常記錄只有在任何人都能做時才行得通。",
  "training.lessons.owner-restaurant-ops.step5": "菜單工程按每道菜的銷量和收益定位：明星、耕馬、謎題和瘦狗。差異頁面將配方說本應離架的與員工餐、損耗和所有其他出庫進行比較——剩下的就是無法解釋的部分。會計匯出將已收貨採購、損耗、員工餐和配方扣減彙總成一本帳，供您入帳。",
  "training.lessons.staff-restaurant-daily.title": "廚房的日常習慣",
  "training.lessons.staff-restaurant-daily.step1": "當有東西被扔掉時，當天就在損耗記錄中記錄：是什麼、多少，以及原因——變質、生產過剩、備餐失誤、退回、灑漏或其他。記錄它會自動將庫存從貨架扣除；您無需單獨調整庫存。",
  "training.lessons.staff-restaurant-daily.step2": "在檢查每個冰箱、冷凍櫃和保溫溫度時記錄它。記錄會保留您的姓名和時間，並標記任何超出安全範圍的讀數——將您對此採取的措施寫為糾正措施。",
  "training.lessons.staff-restaurant-daily.step3": "沽清看板就是現在什麼賣完了。物品一賣完就貼上，讓整個團隊立刻知道，補貨後清除——看板會保留清除人和時間。",
  "training.lessons.staff-restaurant-daily.step4": "當團隊用餐時，將其記錄為員工餐。每份餐都會將其菜餚從貨架扣除，並使用該菜餚配方的配料，如同一次銷售。員工餐是一天的真實成本，應該記錄在案。",
  "training.lessons.mgr-restaurant-invoices.title": "發票、批次和批次執行",
  "training.lessons.mgr-restaurant-invoices.step1": "老闆已將「製作配方」勾選託付給您，它也開啟了廚房的製作工作：供應商發票、保存期限批次和批量生產。輸入帶品項的供應商發票——產品、數量和開票成本——並在有採購單時將其連結。",
  "training.lessons.mgr-restaurant-invoices.step2": "連結採購單後，發票會逐項三方核對：訂購了什麼、收貨了什麼、開票了什麼。一項可能返回相符、短缺、超量、以不同價格開票，或根本不在訂單上。",
  "training.lessons.mgr-restaurant-invoices.step3": "當開票價格與產品記錄成本不同時，會開啟價格提醒。接受提醒會將產品成本設為新的開票價格；忽略它則什麼都不改變。同一發票和產品同時只有一個開啟的提醒。",
  "training.lessons.mgr-restaurant-invoices.step4": "將庫存作為帶保存期限的批次收貨，保存期限頁面會保持批次先到期先出。批次執行將一個配方製作指定份數：它用掉配方的配料，並將成品備餐產品放到貨架上——配方必須先連結到該備餐產品。",
  "training.lessons.mgr-restaurant-invoices.step5": "當供應商針對發票退回款項時——破損的箱子、短缺的交貨、修正的價格——在發票頁面上針對該發票將其記錄為貸項通知單。供應商來自發票本身，通知單計入發票仍欠的金額：發票顯示其已應用的貸項和應付餘額。貸項永遠不能超過其發票，作廢通知單會將其留在記錄中，同時停止計數。 需要紙質版時，可從該行列印此憑證——列印出的單據是您對供應商貸項的自有記錄，並非供應商的單據。",
  "training.lessons.mgr-restaurant-reports.title": "菜單工程、差異和帳目",
  "training.lessons.mgr-restaurant-reports.step1": "老闆已將「菜餚金額」勾選託付給您，它也開啟了廚房的金額報表：菜單工程、差異和會計匯出。這些數字留在企業內部，如同所有菜餚金額。",
  "training.lessons.mgr-restaurant-reports.step2": "菜單工程按每道菜在該期間的銷量和收益定位。明星銷量好、收益好；耕馬銷量好但收益少；謎題收益好但銷量少；瘦狗兩者都不行。",
  "training.lessons.mgr-restaurant-reports.step3": "差異頁面按產品工作：配方說本應離架的，與員工餐、損耗和所有其他出庫並列。剩下的一切都是無法解釋的——而無法解釋的正是需要去解釋的數字。",
  "training.lessons.mgr-restaurant-reports.step4": "會計匯出是廚房的一本帳：已收貨採購、損耗、員工餐和配方扣減，每列帶其日期、數量和成本，可交給記帳人。",
