  "storefronts.ebayDesc": "將您的 eBay 店面連接一次。當商品在 eBay 上售出時，其數量會在這裡自動減少，銷售會記錄在您的出入庫記錄中 — 就像它被掃碼出庫一樣。銷售只單向流動：從 eBay 流入應用程式。",
