  "plansLib.includes.recordPrints": "紙本記錄 — 每週排班表、工資登記表、工時表、培訓記錄、政策與條款、員工名冊和價格清單，可列印已填寫版或手填空白版",
  "training.lessons.staff-record-prints.title": "紙上的記錄",
  "training.lessons.staff-record-prints.step1": "應用程式中幾乎每條記錄現在在文件樣式工作室裡都有一個紙本雙生版：每週排班表、工資登記表、工時表、培訓記錄、您店舖的政策與條款、員工名冊和產品與價格清單 — 在 Business 方案中還有供應商目錄和已填寫的溫度記錄。每份都以您保存的文件樣式、您企業的語言列印，日期按您的方式書寫。",
  "training.lessons.staff-record-prints.step2": "每份紙都在其記錄所在之處。在員工頁面，排班標籤列印您能看到的每個人的整週安排，考勤標籤從其記錄列印工時表。列印只顯示您在該畫面上已經能看到的內容 — 列印永遠不會擴大任何人的可見範圍。",
  "training.lessons.staff-record-prints.step3": "在工資頁面，預覽一個工資期間並列印登記表：每個人、其工時、總額、扣除和淨額都在一張紙上，供工資檔案使用。在培訓頁面，團隊部分列印培訓記錄 — 誰完成了什麼，附測驗分數和日期。",
  "training.lessons.staff-record-prints.step4": "您店舖的政策與條款從設定中列印，與您所寫的完全一致，可交到新員工手裡或貼在牆上。員工頁面列印一頁名冊，產品頁面列印價格清單，在 Business 中供應商頁面列印目錄，溫度記錄頁面為食品安全檔案列印已填寫的記錄。",
  "training.lessons.staff-record-prints.step5": "需要一張手填的表格嗎？列印中心的空白表格現在為這些紙張中的每一份都提供空白雙生版，兩個方案都有：列印一張，用筆填好，與列印件放在一起歸檔。",
  "ageCheck.title": "年齡檢查",
  "ageCheck.intro": "掃描駕駛執照或身分證背面的條碼。你只會得到一個答案——綠色勾號或紅色勾號——而應用程式不會保留掃描中的任何資訊：沒有姓名，沒有號碼，沒有出生日期，沒有任何記錄。",
  "ageCheck.scanPrompt": "將相機對準證件或卡片背面的條碼。",
  "ageCheck.categoryLabel": "正在賣什麼？",
  "ageCheck.category.alcohol": "酒類",
  "ageCheck.category.tobacco": "菸草",
  "ageCheck.category.other": "其他有年齡限制的商品",
  "ageCheck.lineNote": "你對{category}的界線：{age}歲及以上",
  "ageCheck.pass": "年齡足夠——可以出售。",
  "ageCheck.fail": "年齡不夠——不要進行這筆交易。",
  "ageCheck.expired": "這張證件已過期——不通過。",
  "ageCheck.unreadable": "那個碼不是我們能讀取的身分證條碼。請試試證件背面的條碼。",
  "ageCheck.checkAnother": "再檢查一個",
  "ageCheck.back": "返回掃描產品",
  "ageCheck.keepsNothing": "這次掃描的任何資訊都不會被保存、傳送或記錄。答案就是全部，離開此畫面後就會消失。",
  "settings.ageLines.title": "年齡界線",
  "settings.ageLines.description": "顧客在每種交易中必須達到的年齡，掃描頁面的年齡檢查使用它。這些界線由你來設定——請按照你的企業所在地的法律來設定。應用程式以酒類21歲、菸草21歲、其他有年齡限制的商品18歲為起點。",
  "settings.ageLines.alcohol": "酒類——最低年齡",
  "settings.ageLines.tobacco": "菸草——最低年齡",
  "settings.ageLines.other": "其他有年齡限制的商品——最低年齡",
  "plansLib.includes.ageCheck": "用證件掃描進行年齡檢查——掃描身分證背面獲得綠色或紅色勾號，證件中的任何資訊都不會被保留",
  "training.lessons.scanner-age-check.title": "用證件掃描檢查年齡",
  "training.lessons.scanner-age-check.step1": "有些商品只能出售給超過一定年齡的顧客。在掃描頁面，打開年齡檢查，選擇正在賣什麼——酒類、菸草，或其他有年齡限制的商品——然後掃描顧客駕駛執照或身分證背面的條碼。",
  "training.lessons.scanner-age-check.step2": "答案是兩個勾號中的一個。綠色勾號表示顧客年齡足夠，可以出售。紅色勾號表示他還沒有達到該類別的界線，或者證件已過期——無論哪種情況，都不應進行交易。",
  "training.lessons.scanner-age-check.step3": "應用程式不會保留掃描中的任何資訊。任何姓名、證件號碼或出生日期都不會在任何地方被保存、傳送或記錄：檢查回答那一個問題後便消失。沒有已檢查證件的清單可供回看——這是有意為之。",
  "training.lessons.scanner-age-check.step4": "年齡界線屬於店主，他在設定中按照企業所在地的法律來設定。它們可以因地而異，也可以與應用程式的起始界線不同，而檢查始終遵循你所在企業的店主界線。",
  "training.lessons.scanner-age-check.step5": "如果碼無法讀取，畫面會明確說明。擦拭條碼後再試一次，或要求出示另一張證件。不是身分證條碼的碼永遠不會獲得綠色勾號。",
  "training.heading.general": "通用培訓",
  "training.heading.restaurant": "餐廳培訓",
  "training.own.title": "添加您自己的培訓",
  "training.own.help": "寫一份您自己的培訓——您的安全規則、您的注意事項、您做事的方式——然後建立它的測驗，並勾選應該參加的人。您的培訓只留在這個企業裡；其他企業的任何人都永遠看不到。",
  "training.own.newTraining": "新培訓",
