  "training.own.modeAutoHint": "輸入的答案如果與您期望的答案幾乎逐字相符，就當場算作正確，並計入分數。",
  "training.own.modeReview": "發給我來批改",
  "training.own.modeReviewHint": "輸入的答案會連同這次作答一起送到您這裡，當您標記為通過時，培訓才算完成——或者退回重做。",
