  "training.own.pendingReview": "在店主處待批改",
  "training.own.markPass": "標記為通過",
  "training.own.sectionTitle": "來自店主的培訓",
  "training.own.sectionHelp": "您的店主為這家店寫了這些培訓。逐個閱讀，然後回答店主的問題。",
  "training.own.read": "培訓",
  "training.own.noMaterial": "店主還沒有添加培訓文字。",
  "training.own.pendingNote": "您的答案在店主那裡。當店主標記為通過時，這個培訓才算完成。",
  "plansLib.includes.ownTraining": "添加您自己的培訓——為您的團隊編寫自己的培訓和測驗",
  "training.lessons.owner-own-training.title": "添加您自己的培訓",
  "training.lessons.owner-own-training.step1": "在培訓頁面的最末尾有「添加您自己的培訓」框。打開它，開始一個新培訓，並給它一個標題——您的安全規則、您的注意事項、您做事的方式。",
  "training.lessons.owner-own-training.step2": "在框裡用您自己的話寫下培訓內容本身，或者改為上傳文件——PDF、文本、Word 或 OpenDocument 文件。輸入的文字會替換已保存的文件，文件也會替換輸入的文字。",
  "training.lessons.owner-own-training.step3": "在下面建立它的測驗：想出多少題都可以，選擇題和書面回答題自由混合。對於書面題，寫下您期望的答案；對於選擇題，標記正確的那個。",
  "training.lessons.owner-own-training.step4": "設定通過線，並選擇書面回答的判定方式：用您的答案鑰匙幾乎逐字核對，或者發給您來標記通過或退回。然後準確勾選哪些團隊成員參加這個培訓——只有他們能看到它。",
  "training.lessons.owner-own-training.step5": "您保存的每個培訓都在框裡獨立存在，有自己的問題、通過線和勾選，您可以添加任意多個。結果會出現在每個培訓下方的框裡；只有當服務器核查了一次通過的作答，培訓才算完成——或者在批改模式下，當您標記為通過時。",
  "apiErrors.ownTrainingOwnerWrites": "這些培訓只有店主能寫。",
  "apiErrors.ownTrainingNotHere": "那個培訓不在這裡。",
  "apiErrors.ownTrainingTooLong": "那個培訓太長，無法在這裡輸入。您可以改為上傳文件。",
