  "apiErrors.ownTrainingWrittenMode": "書面回答會用鑰匙核對，或發送給店主。",
  "print.pool.title": "產生條碼",
  "print.pool.intro": "在商品存在之前就產生條碼。把它們列印出來，貼在沒有自己條碼的商品上；日後掃描其中一個時，應用程式會認出這個碼，並提議新增該商品。",
  "print.pool.countLabel": "您需要多少個條碼？",
  "print.pool.generate": "產生",
  "print.pool.generating": "正在產生…",
  "print.pool.minted": "已向您的碼池新增 {count} 個新條碼。",
  "print.pool.waiting": "您的碼池中有 {count} 個未使用的條碼在等待。",
  "print.pool.printNow": "立即列印",
  "print.pool.savePdf": "儲存為 PDF",
  "print.pool.failed": "無法產生那些條碼。請重試。",
  "scan.pool.title": "您自己列印的條碼之一",
  "scan.pool.body": "這還不是您店裡的商品——這是您預先列印的條碼。您想把它新增為商品嗎？",
  "plansLib.includes.barcodePool": "條碼池——預先列印條碼，然後在每個商品的條碼被掃描時新增該商品",
  "training.lessons.owner-barcode-pool.title": "在商品之前列印條碼",
  "training.lessons.owner-barcode-pool.step1": "有些商品沒有自己的條碼——手工製品、您自己的書包、任何您親手製作或組合的東西。在列印部分，「產生條碼」入口會在商品存在之前就產生編碼。",
  "training.lessons.owner-barcode-pool.step2": "說出您需要的數量——沒有上限——應用程式就會向您企業的條碼池鑄造同樣數量的新碼。它們只屬於您的企業，絕不會發放兩次，產生它們也不會產生商品或庫存。",
  "training.lessons.owner-barcode-pool.step3": "在它們產生的那一刻做出選擇：立即列印成標籤，或儲存為 PDF 以便日後列印。無論哪種方式，這些碼都在池中，列印出的標籤與碼池完全一致。",
  "training.lessons.owner-barcode-pool.step4": "在製作每件商品時給它貼上一個標籤。未使用的碼只是在池中等待——不用著急，它們也不會過期。",
  "training.lessons.owner-barcode-pool.step5": "當貼有標籤的商品日後被掃描時，應用程式會認出它自己列印的碼，並提議新增該商品，碼已經填好。新增之後，這個碼就成為該商品的碼，像其他任何碼一樣被掃描。",
  "apiErrors.poolOwnerMints": "只有店主才能為碼池產生條碼。",
