  "training.lessons.staff-checklists.title": "做清單",
  "training.lessons.staff-checklists.step1": "清單是您的生意運轉所靠的清單——開店、打烊、清潔,以及店主設定的一切。在「清單」裡找到它們:今天的清單在最上面,準備好勾選。",
  "training.lessons.staff-checklists.step2": "當您真正做完一個項目時再勾選它。每個勾選都會記下是誰做的、什麼時候做的,這樣下一個人——以及在家的店主——都能看到什麼做完了、什麼還缺。",
  "training.lessons.staff-checklists.step3": "有些項目在勾選前要求證明:做完工作的照片、代碼的掃描,或輸入的溫度。先新增證明,再勾選——沒有證明,項目不會被勾選。",
  "training.lessons.staff-checklists.step4": "不小心勾選了什麼?取消它的勾選——但只能取消自己的。經理或店主可以取消任何人的,因為勾選是帶名字的記錄。",
  "training.lessons.staff-checklists.step5": "做清單從來不需要許可。建立範本並選擇分配給誰是店主的工作,或店主給予清單範本勾選的人的工作。",
