  "training.lessons.staff-food-safety.title": "維護食品安全檔案",
  "training.lessons.staff-food-safety.step1": "食品安全檔案位於餐廳角落的食品安全貨架上：溫度日志、冷卻、復熱和消毒劑日志、證書、安全數據表和檢查包。",
  "training.lessons.staff-food-safety.step2": "超出範圍的讀數在其備注說明你做了什麼 — 重新冷卻、重新加熱、重新配製消毒劑、丟棄 — 之前不算完成。沒有備注，就不保存：該條目不成立。",
  "training.lessons.staff-food-safety.step3": "像記錄溫度一樣記錄冷卻、復熱和消毒劑檢查：你檢查了什麼、讀數，以及未達標時的糾正措施。",
  "training.lessons.staff-food-safety.step4": "證書在到期前會發出警告。當你的證書發出警告時，告訴業主 — 任何人都可以隨時在貨架上閱讀安全數據表。",
  "training.lessons.staff-food-safety.step5": "在檢查之前 — 或任何時候 — 從食品安全貨架運行模擬檢查，並按檢查員的日期打印檢查就緒包。",
